var FEN = ['Generalização', 'Discriminação', 'Extinção', 'Recuperação espontânea', 'Sensibilização', 'Habituação'];
var MEM = ['Semântica', 'Episódica', 'Procedimental', 'Sensorial'];
var GES = ['Pregnância', 'Unidade', 'Segregação', 'Continuidade', 'Proximidade', 'Fechamento', 'Semelhança', 'Unificação'];
var NIV = ['Nominal', 'Ordinal', 'Intervalar', 'De razão'];
ferramentas('12', 'Fenômenos e Processos Psicológicos Básicos', '02', [
  {titulo:'Que fenômeno é esse? (condicionamento clássico)', sub:'Leia a situação e identifique o fenômeno do condicionamento clássico, segundo a aula 5.', opcoes:FEN, nota:'Situações fictícias, com base na aula 5 de Fenômenos e Processos.', cenarios:[
    {situacao:'Um bebê aprendeu a dizer "au au" para o cachorro da casa e agora diz "au au" para o gato, o cavalo e a vaca do livro.', correta:'Generalização', explicacao:'A mesma resposta para estímulos semelhantes (animais de quatro patas) é generalização.'},
    {situacao:'Depois de um tempo, a criança passa a dizer "au au" só para cachorros, e chama o gato de "miau".', correta:'Discriminação', explicacao:'Dar a resposta específica a um único tipo de estímulo entre os semelhantes é discriminação.'},
    {situacao:'Entre vários homens de barba na festa, o bebê estende os braços só para o próprio pai.', correta:'Discriminação', explicacao:'Reconhecer um estímulo específico entre vários parecidos é discriminação.'},
    {situacao:'Um cão salivava quando a luz acendia, porque a carne vinha em seguida. A carne parou de vir, e semanas depois ele já não saliva para a luz.', correta:'Extinção', explicacao:'Desfeito o pareamento entre luz e carne, a resposta condicionada enfraquece e desaparece.'},
    {situacao:'Depois da extinção, o experimentador volta a dar a carne logo após a luz, e o cão volta a salivar quando a luz acende.', correta:'Recuperação espontânea', explicacao:'É a recuperação como descrita na aula: o vínculo se restabelece e a resposta volta.'},
    {situacao:'Na primeira noite na casa da tia, perto da pista do aeroporto, Júlia acorda com cada avião que pousa.', correta:'Sensibilização', explicacao:'Estar muito sensível a um estímulo do ambiente é sensibilização.'},
    {situacao:'A tia de Júlia mora perto do aeroporto há dez anos e diz: "Que barulho? Nem escuto mais."', correta:'Habituação', explicacao:'Acostumar-se ao estímulo a ponto de não percebê-lo é habituação.'},
    {situacao:'Quem trabalha na Ilha do Fundão já nem sente o cheiro de gás que incomoda tanto os visitantes.', correta:'Habituação', explicacao:'O exemplo da aula: o trabalhador se acostumou ao cheiro.'},
    {situacao:'Uma criança que tem medo do jaleco branco do pediatra passa a chorar também quando vê o jaleco branco do farmacêutico.', correta:'Generalização', explicacao:'O medo se estende a um estímulo semelhante: generalização.'},
    {situacao:'Recém-chegado perto da igreja, Pedro se irrita com o sino a cada hora; não consegue se concentrar em nada.', correta:'Sensibilização', explicacao:'O estímulo se torna impregnante e é percebido com muita facilidade: sensibilização.'}]},
  {titulo:'ENC, RNC, EC ou RC?', sub:'Na situação, identifique o que é o elemento destacado entre aspas, no esquema do condicionamento clássico.', opcoes:['Estímulo não-condicionado (ENC)', 'Resposta não-condicionada (RNC)', 'Estímulo condicionado (EC)', 'Resposta condicionada (RC)'], nota:'Lembre: o EC era um estímulo neutro antes da associação.', cenarios:[
    {situacao:'Pavlov: a "carne" faz o cão salivar naturalmente.', correta:'Estímulo não-condicionado (ENC)', explicacao:'A carne provoca a resposta de forma natural, sem aprendizagem.'},
    {situacao:'Pavlov: a "salivação diante da carne", que acontece sem aprendizagem.', correta:'Resposta não-condicionada (RNC)', explicacao:'É a resposta reflexa, natural.'},
    {situacao:'Pavlov: a "luz" que, depois de associada à carne, passou a fazer o cão salivar.', correta:'Estímulo condicionado (EC)', explicacao:'Era neutra; associada à carne, tornou-se estímulo condicionado.'},
    {situacao:'Pavlov: a "salivação diante da luz", sem nenhuma carne por perto.', correta:'Resposta condicionada (RC)', explicacao:'É a resposta aprendida ao estímulo condicionado.'},
    {situacao:'No dentista, a "dor" do tratamento deixa Ana tensa.', correta:'Estímulo não-condicionado (ENC)', explicacao:'A dor provoca tensão naturalmente.'},
    {situacao:'Hoje, o "barulho do motorzinho", que sempre vinha junto da dor, já deixa Ana tensa.', correta:'Estímulo condicionado (EC)', explicacao:'O barulho era neutro e, associado à dor, virou estímulo condicionado.'},
    {situacao:'A "tensão de Ana ao ouvir o motorzinho", antes de qualquer dor.', correta:'Resposta condicionada (RC)', explicacao:'É a resposta aprendida ao barulho.'},
    {situacao:'O "susto" que um barulho muito alto e repentino provoca em qualquer bebê.', correta:'Resposta não-condicionada (RNC)', explicacao:'É uma reação natural, sem aprendizagem.'}]},
  {titulo:'Que memória é essa?', sub:'Leia a situação e identifique o tipo de memória envolvido, segundo o texto 5.', opcoes:MEM, nota:'Semântica e episódica são declarativas; a procedimental é não declarativa.', cenarios:[
    {situacao:'Você sabe que a água ferve a 100 °C ao nível do mar.', correta:'Semântica', explicacao:'Conhecimento geral sobre o mundo: memória semântica.'},
    {situacao:'Você se lembra do que comeu no almoço do seu último aniversário.', correta:'Episódica', explicacao:'Um detalhe da própria vida: memória episódica.'},
    {situacao:'Você amarra o cadarço sem pensar em cada passo.', correta:'Procedimental', explicacao:'Saber fazer, sem precisar verbalizar: procedimental.'},
    {situacao:'Por uma fração de segundo, a imagem do relâmpago continua "na sua frente" depois que ele some.', correta:'Sensorial', explicacao:'A memória icônica, sensorial, guarda a imagem por um instante.'},
    {situacao:'Você sabe que Freud criou a psicanálise.', correta:'Semântica', explicacao:'Um fato do conhecimento geral: semântica.'},
    {situacao:'Você dirige até a faculdade enquanto conversa, sem pensar nas marchas.', correta:'Procedimental', explicacao:'Habilidade automatizada: memória procedimental.'},
    {situacao:'Você se lembra do primeiro dia de aula na faculdade e de quem sentou ao seu lado.', correta:'Episódica', explicacao:'Evento vivido por você: episódica.'},
    {situacao:'Alguém fala com você enquanto você lê, e por um instante você ainda "ouve" a última frase dita.', correta:'Sensorial', explicacao:'A memória ecoica guarda o som por um instante.'}]},
  {titulo:'Qual lei da Gestalt?', sub:'Leia a descrição e identifique a lei da Gestalt, segundo o texto 6.', pool:GES, nota:'Exemplos baseados no texto 6. A lei básica é a da boa forma (pregnância).', cenarios:[
    {situacao:'Num logotipo simples, você reconhece na hora um coração, sem precisar examinar.', correta:'Pregnância', explicacao:'A forma simples e estável se impõe: pregnância.'},
    {situacao:'Você vê uma bicicleta como um objeto só, embora ela tenha rodas, quadro e guidão.', correta:'Unidade', explicacao:'Um elemento é percebido como item único, mesmo divisível: unidade.'},
    {situacao:'Na mesa bagunçada, você distingue tesoura, lápis, borracha e régua.', correta:'Segregação', explicacao:'Identificar itens distintos no mesmo espaço: segregação.'},
    {situacao:'Os gomos da bola de futebol são vistos como uma superfície contínua.', correta:'Continuidade', explicacao:'Elementos na direção do padrão são integrados: continuidade.'},
    {situacao:'Seis pontos estão em dois grupos de três, bem separados: você vê dois grupos.', correta:'Proximidade', explicacao:'Elementos próximos parecem formar um todo: proximidade.'},
    {situacao:'O contorno de um urso tem falhas, mas você vê o urso inteiro.', correta:'Fechamento', explicacao:'Completamos a figura para que fique fechada: fechamento.'},
    {situacao:'Num campo de bolinhas, as vermelhas parecem formar um grupo separado das azuis.', correta:'Semelhança', explicacao:'Elementos semelhantes parecem do mesmo todo: semelhança.'},
    {situacao:'Uma árvore de Natal, com enfeites de formas e cores variadas, é vista como um conjunto só.', correta:'Unificação', explicacao:'Elementos distintos vistos como conjunto, pela semelhança, proximidade e pregnância: unificação.'}]},
  {titulo:'Que nível de medida?', sub:'Leia a variável e identifique o nível de medida.', opcoes:NIV, nota:'Os quatro níveis do texto "A Psicologia como ciência".', cenarios:[
    {situacao:'Classificar os alunos em aprovados e reprovados.', correta:'Nominal', explicacao:'Categorias, sem ordem: nominal.'},
    {situacao:'Ordenar crianças em agressividade baixa, média e alta.', correta:'Ordinal', explicacao:'Há ordem, mas não distâncias iguais garantidas: ordinal.'},
    {situacao:'Escores padronizados de um teste de inteligência, sem zero absoluto.', correta:'Intervalar', explicacao:'Unidades iguais, sem zero absoluto: intervalar.'},
    {situacao:'Horas de privação de alimento de um rato no experimento.', correta:'De razão', explicacao:'Tem zero absoluto e permite dizer "o dobro": razão.'},
    {situacao:'Tipo sanguíneo dos participantes (A, B, AB, O).', correta:'Nominal', explicacao:'Categorias sem ordem: nominal.'},
    {situacao:'Posição de chegada numa corrida (1º, 2º, 3º).', correta:'Ordinal', explicacao:'Indica ordem, não a distância entre os corredores: ordinal.'},
    {situacao:'Intensidade de um choque elétrico, medida em volts.', correta:'De razão', explicacao:'Zero absoluto e proporções: razão.'},
    {situacao:'Número de respostas certas num teste de memória.', correta:'De razão', explicacao:'Zero acertos é ausência real: razão.'}]}
]);

